-- -------------------------------------------------------------------------
-- Table: yield_logs (25 rows)
-- -------------------------------------------------------------------------
DROP TABLE IF EXISTS yield_logs CASCADE;
CREATE TABLE IF NOT EXISTS yield_logs (
    id SERIAL PRIMARY KEY,
    plot_id INTEGER,
    farmer_id INTEGER,
    harvest_date TEXT,
    tapping_round TEXT,
    fresh_latex_kg NUMERIC,
    drc_percent NUMERIC,
    dry_rubber_kg NUMERIC,
    price_per_kg NUMERIC,
    total_revenue NUMERIC,
    buyer_name TEXT,
    notes TEXT,
